const VL_mos=(x,y,mode,o={})=>{const p=o.p,well=p?'#FFE3E3':VL_WELL,wst=p?'#C92A2A':VL_WELLS,body=p?'#E7F5FF':VL_BODY,bst=p?'#1864AB':VL_BODYS,ch=p?MAG:VL_CH;
 let s=`<g transform="translate(${x} ${y})">`+`<rect x="0" y="40" width="300" height="90" rx="6" fill="${body}" stroke="${bst}" stroke-width="2"/>`;
 if(o.dep)s+=`<rect x="85" y="40" width="130" height="${o.dep}" fill="${GRY}" fill-opacity=".28"/>`+VL_L(85,40+o.dep,215,40+o.dep,VL_GREY,2,'stroke-dasharray="6 5"');
 s+=`<rect x="12" y="40" width="76" height="36" rx="8" fill="${well}" stroke="${wst}" stroke-width="2"/><rect x="212" y="40" width="76" height="36" rx="8" fill="${well}" stroke="${wst}" stroke-width="2"/>`;
 s+=VL_T(50,66,p?'p⁺':'n⁺',{fs:22,fw:800,a:'middle',fill:wst})+VL_T(250,66,p?'p⁺':'n⁺',{fs:22,fw:800,a:'middle',fill:wst});
 if(mode==='full')s+=`<polygon points="88,40 212,40 212,48 88,57" fill="${ch}" fill-opacity=".75"/>`;
 if(mode==='pinch')s+=`<polygon points="88,40 176,40 88,57" fill="${ch}" fill-opacity=".75"/>`;
 s+=`<rect x="84" y="31" width="132" height="9" fill="#F1F3F5" stroke="${VL_GREY}" stroke-width="1.5"/><rect x="84" y="2" width="132" height="29" rx="5" fill="#FFFFFF" stroke="${BLU}" stroke-width="2.5"/>`+VL_T(150,24,'G',{fs:20,fw:800,a:'middle',fill:BLU});
 s+=VL_T(50,24,'S',{fs:20,fw:800,a:'middle',fill:VL_GREY})+VL_T(250,24,'D',{fs:20,fw:800,a:'middle',fill:VL_GREY});
 return s+'</g>'};
/* the threshold of the worked device against source-body bias (VT0 = 0.45 V, γ = 0.2115 √V, 2φF = 0.8171 V) */
const VL_vt=v=>0.45+0.2115*(Math.sqrt(0.8171+v)-Math.sqrt(0.8171));
